#!/usr/bin/env python3
"""Is the first-order transfer image Im T_1 (mod J) the C[x][d]-module generated by the single THM-4671 class b_N?
(S44.)  Computes, bidegree by bidegree, the span of {monomial * d^k b_N} + J and compares its dimension above J with
rank T_1 (from vir_transfer_orders: order-1 counts, recomputed here directly).
Usage: python order1_cyclic_check_20261018.py p q Dmax
Session opus-2026-10-18-S44.
"""
import os, sys, json
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, '..', 'voa_singular_support'))
sys.path.insert(0, HERE)
from vir_ss import block, mult_x, deriv
from vir_quantum_transfer_20261018 import Transfer, by_length, to_rows, rank, left_nullspace


def main():
    p, q, Dmax = map(int, sys.argv[1:4])
    P = 2147483647
    T = Transfer(p, q, Dmax, P)
    N = T.N
    # b_N: T_1 of the unique cycle at (2N+3, N+1)
    D0, r0 = 2 * N + 3, N + 1
    B1 = T.k1_basis(D0, r0)
    rows1, nc = T.d1_rows(B1, D0, r0)
    cyc = left_nullspace(rows1, nc, P)
    assert len(cyc) >= 1
    bN = None
    for z in cyc:
        t = by_length(T.phi_of(z, B1)).get(N, {})
        if t:
            bN = t
            break
    assert bN is not None
    span = {(D0, N): [bN]}
    out = []
    ok = True
    for D in range(D0, Dmax + 1):
        for s in range(N, D // 2 + 1):
            vecs = list(span.get((D, s), []))
            # products x_j * span(D-j-2, s-1) and d span(D-1, s)
            for j in range(0, D):
                for v in span.get((D - j - 2, s - 1), []):
                    vecs.append({k: x % P for k, x in mult_x(v, D - j - 2, s - 1, j).items()})
            for v in span.get((D - 1, s), []):
                dv = deriv(v)
                if dv:
                    vecs.append({k: x % P for k, x in dv.items()})
            if not vecs:
                continue
            span[(D, s)] = vecs
            J = T.ss.J.get((D, s), [])
            rJ, n = to_rows(J, D, s, P)
            rv, _ = to_rows(vecs, D, s, P)
            rkJ = rank(rJ, n, P)
            dim_mod = rank(rJ + rv, n, P) - rkJ
            # T_1 rank at (D, s): cycles of length s+1
            B = T.k1_basis(D, s + 1)
            rt1 = 0
            if B:
                r1, nc1 = T.d1_rows(B, D, s + 1)
                cy = left_nullspace(r1, nc1, P)
                t1 = [by_length(T.phi_of(z, B)).get(s, {}) for z in cy]
                rt, _ = to_rows([t for t in t1 if t], D, s, P)
                rt1 = rank(rJ + rt, n, P) - rkJ
                both = rank(rJ + rt + rv, n, P) - rkJ
                if not (both == rt1 == dim_mod):
                    ok = False
            out.append(dict(D=D, s=s, span_bN=dim_mod, T1=rt1))
            # keep a reduced basis to limit growth
            span[(D, s)] = vecs[:max(1, 4 * n)]
    print('Vir_(%d,%d) N=%d: Im T_1 == C[x][d] b_N (mod J) at every bidegree through D=%d: %s' % (p, q, N, Dmax, ok))
    print('  sample:', [(x['D'], x['s'], x['span_bN'], x['T1']) for x in out if x['T1']][:12])
    json.dump(dict(p=p, q=q, Dmax=Dmax, ok=ok, rows=out), open(os.path.join(HERE, 'order1_cyclic_%d_%d_D%d.json' % (p, q, Dmax)), 'w'), indent=1)


if __name__ == '__main__':
    main()
